<?php
declare(strict_types=1);
require_once __DIR__.'/../src/helpers.php';require_once __DIR__.'/../src/EmployeeRepository.php';require_once __DIR__.'/../src/EmployeeValidator.php';
$repo=new EmployeeRepository(__DIR__.'/../dataset/employees.csv');$validator=new EmployeeValidator();$employees=$repo->all();$errors=[];$success=false;$values=['name'=>'','email'=>'','department'=>'','experience'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){$r=$validator->validate($_POST);$values=$r['values'];$errors=$r['errors'];if(!$errors){$success=true;$employees[]=['id'=>count($employees)+1,'name'=>$values['name'],'department'=>$values['department'],'experience'=>(int)$values['experience'],'email'=>$values['email']];$values=['name'=>'','email'=>'','department'=>'','experience'=>''];}}
$filter=trim((string)($_GET['department']??''));if($filter!=='')$employees=array_values(array_filter($employees,fn($x)=>mb_strtolower($x['department'])===mb_strtolower($filter)));$departments=$repo->departments();$cases=json_decode((string)file_get_contents(__DIR__.'/../dataset/form_cases.json'),true)??[];
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Сотрудники — ТРПО 04</title><style>
body{margin:0;background:#f3f5fa;color:#172033;font:16px system-ui}header{background:#172554;color:white;padding:24px max(20px,calc((100% - 1000px)/2))}main{max-width:1000px;margin:28px auto;padding:0 18px}.panel{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block}input,select{width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:8px;box-sizing:border-box}button,.btn{background:#315efb;color:white;border:0;padding:10px 14px;border-radius:8px;text-decoration:none}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #e2e8f0}.error{color:#b91c1c}.muted{color:#64748b}@media(max-width:600px){.grid{grid-template-columns:1fr}}
</style></head><body><header><h1>Учёт сотрудников</h1>Практическая работа №04 · ТРПО</header><main><p class="muted">Солопов Антон · ЭПБО-01-25</p><section class="panel"><h2>Добавить сотрудника</h2><?php if($success):?><p>Запись добавлена в список текущего запроса.</p><?php endif;?><?php if($errors):?><p class="error">Проверьте поля формы.</p><?php endif;?><form method="post"><div class="grid"><?php foreach(['name'=>'Имя','email'=>'Email','department'=>'Отдел','experience'=>'Стаж'] as $k=>$label):?><div><label><?=e($label)?><input name="<?=$k?>" value="<?=e($values[$k])?>" <?=$k==='email'?'type="email"':($k==='experience'?'type="number" min="0" max="60"':'')?> required></label><?php if(isset($errors[$k])):?><small class="error"><?=e($errors[$k])?></small><?php endif;?></div><?php endforeach;?></div><p><button>Добавить</button></p></form></section><section class="panel"><h2>Сотрудники</h2><form method="get"><label>Отдел<select name="department"><option value="">Все отделы</option><?php foreach($departments as $d):?><option <?=$filter===$d?'selected':''?>><?=e($d)?></option><?php endforeach;?></select></label><p><button>Фильтровать</button> <a class="btn" href="/">Сбросить</a></p></form><p>Записей: <?=count($employees)?></p><div style="overflow-x:auto"><table><tr><th>ID</th><th>Имя</th><th>Отдел</th><th>Стаж</th><th>Email</th></tr><?php foreach($employees as $x):?><tr><td><?=$x['id']?></td><td><?=e($x['name'])?></td><td><?=e($x['department'])?></td><td><?=$x['experience']?></td><td><?=e($x['email'])?></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Контрольные кейсы</h2><ul><?php foreach($cases as $case):$r=$validator->validate(['name'=>$case['name'],'email'=>'a@example.test','department'=>'Тест','experience'=>(string)$case['experience']]);?><li><?=e($case['case'])?> — <?=((!$r['errors'])===(bool)$case['valid'])?'пройден':'ошибка'?></li><?php endforeach;?></ul></section></main></body></html>